 var items=await root.ShiliRepository.listAnniversaries(db(),String(uid()));if(items.length){main.appendChild(el('h2','shili-section','值得记住的日子'));items.slice(0,2).forEach(function(a){main.appendChild(btn(a.title+' · '+a.date,function(){go('calendar');},'shili-event-link'));});}
 if(g.length){main.appendChild(el('h2','shili-section','最近的心意'));g.sort(function(a,b){return b.realTimestamp-a.realTimestamp;}).slice(0,2).forEach(function(gift){main.appendChild(btn((gift.status==='received'&&!gift.openedAt)?'一份待拆封的礼物':gift.sourceType==='shili-ai'&&gift.status==='draft'?'角色正在准备礼物':gift.name,function(){state.selected=gift.id;state.view=null;render();},'shili-event-link'));});}
