root.showShiliPage=function(){if(document.getElementById('shili-page')&&!mayLeave())return;state.tab='home';state.selected=null;state.view=null;shell();render();};
root.addEventListener('shili:gift-updated',function(e){if(String(uid())!==String(e.detail?.ownerUid)||!document.getElementById('shili-page'))return;if((!state.selected&&['home','cabinet'].includes(state.tab))||(String(state.selected)===String(e.detail.giftId)&&!state.view))render();});
root.document.addEventListener('wanwan-wechat-identity-changed',function(){var currentPage=document.getElementById('shili-page');if(!currentPage||currentPage.dataset.ownerUid===String(uid()))return;formGuards=[];state.tab='home';state.selected=null;state.view=null;shell();render();});
root.ShiliUI={openGift:function(id){if(document.getElementById('shili-page')&&!mayLeave())return;state.tab='cabinet';state.selected=id;state.view=null;shell();render();}};
